import { supabase } from '../supabaseClient'
import type { SessionRow } from '../types'
import type { TravelSession } from '../../utils/travelSession'
import { ALL_TRACKED_FIELDS } from '../../utils/travelSession'

function sessionToData(session: TravelSession): Record<string, unknown> {
  const data: Record<string, unknown> = {}
  for (const f of ALL_TRACKED_FIELDS) {
    data[f] = session[f]
  }
  data['lastUpdatedAt'] = session.lastUpdatedAt
  return data
}

function dataToSession(data: Record<string, unknown>): TravelSession {
  return data as unknown as TravelSession
}

export const sessionRepository = {
  async create(session: TravelSession): Promise<SessionRow | null> {
    const { data, error } = await supabase
      .from('sessions')
      .insert({
        destination: session.destination || '',
        departure_city: session.departureCity || '',
        session_data: sessionToData(session),
        completion_percentage: session.completionPercentage,
        decision_confirmed: session.decisionProfileConfirmed,
      })
      .select()
      .maybeSingle()
    if (error) throw error
    return data
  },

  async update(id: string, session: TravelSession): Promise<SessionRow | null> {
    const { data, error } = await supabase
      .from('sessions')
      .update({
        destination: session.destination || '',
        departure_city: session.departureCity || '',
        session_data: sessionToData(session),
        completion_percentage: session.completionPercentage,
        decision_confirmed: session.decisionProfileConfirmed,
      })
      .eq('id', id)
      .select()
      .maybeSingle()
    if (error) throw error
    return data
  },

  async getById(id: string): Promise<SessionRow | null> {
    const { data, error } = await supabase
      .from('sessions')
      .select('*')
      .eq('id', id)
      .maybeSingle()
    if (error) throw error
    return data
  },

  async listByUser(limit: number = 20): Promise<SessionRow[]> {
    const { data, error } = await supabase
      .from('sessions')
      .select('*')
      .order('created_at', { ascending: false })
      .limit(limit)
    if (error) throw error
    return data ?? []
  },

  async delete(id: string): Promise<boolean> {
    const { error } = await supabase.from('sessions').delete().eq('id', id)
    if (error) throw error
    return true
  },

  async getSessionData(id: string): Promise<TravelSession | null> {
    const row = await this.getById(id)
    if (!row) return null
    return dataToSession(row.session_data)
  },

  dataToSession,
  sessionToData,
}

export interface OwnershipCheckResult {
  hasOwnership: boolean
  error: string | null
}

export function validateOwnership(resourceUserId: string, currentUserId: string | undefined): OwnershipCheckResult {
  if (!currentUserId) {
    return { hasOwnership: false, error: 'المستخدم غير مسجل الدخول' }
  }
  if (resourceUserId !== currentUserId) {
    return { hasOwnership: false, error: 'لا تملك صلاحية الوصول إلى هذا المورد' }
  }
  return { hasOwnership: true, error: null }
}

export function sanitizeInput(input: string): string {
  return input.trim().slice(0, 1000)
}

export function validateDestination(destination: string): string | null {
  if (!destination || !destination.trim()) return 'الوجهة مطلوبة'
  if (destination.length > 200) return 'اسم الوجهة طويل جداً'
  return null
}

export function validateSessionData(data: unknown): boolean {
  if (!data || typeof data !== 'object') return false
  return true
}

export interface RateLimitEntry {
  key: string
  count: number
  windowStart: number
}

const rateLimitStore = new Map<string, RateLimitEntry>()
const RATE_LIMIT_WINDOW_MS = 60_000

export function checkRateLimit(key: string, maxRequests: number = 30): boolean {
  const now = Date.now()
  const entry = rateLimitStore.get(key)
  if (!entry || now - entry.windowStart > RATE_LIMIT_WINDOW_MS) {
    rateLimitStore.set(key, { key, count: 1, windowStart: now })
    return true
  }
  if (entry.count >= maxRequests) {
    return false
  }
  entry.count++
  return true
}

export function clearRateLimit(key: string): void {
  rateLimitStore.delete(key)
}

